import {api,get,post,patch,esc,rupees,dateTime,paisaFromInput,uuid} from './api.js';
let me=null,collapsed=false,cart=[],selectedCustomer=null,saleKind='on_site',payMethod='cash',discount=0,delivery=0,searchTimer=null;
const $=sel=>document.querySelector(sel);
const roleName=r=>({admin:'Super Admin',shop_manager:'Shop Manager',cashier:'Cashier',warehouse_manager:'Warehouse Manager',warehouse_staff:'Warehouse Staff'}[r]||r);
const isAdmin=()=>me?.role==='admin',canManageShop=()=>isAdmin()||me?.role==='shop_manager',canManageWh=()=>isAdmin()||me?.role==='warehouse_manager',canOperateWh=()=>canManageWh()||me?.role==='warehouse_staff';
const shopId=()=>isAdmin()?1:me.location_id,whId=()=>isAdmin()?2:me.location_id;
const E=esc;
const fmt=p=>'Rs '+rupees(p);
const statusBadge=s=>`<span class="badge ${['received','completed','processing','approved','synced'].includes(s)?'success':['pending','ordered','on-hold','in_transit','partially_received'].includes(s)?'warn':['rejected','cancelled','failed'].includes(s)?'danger':'info'}">${E(s||'—')}</span>`;
const errorView=e=>`<div class="card card-pad"><div class="error"><b>Could not load this page:</b> ${E(e.message)}</div><div class="tip">Check the database, permissions and network connection.</div><button class="btn" data-action="reload">Try again</button></div>`;
function toast(message,bad=false){$('.toast')?.remove();const div=document.createElement('div');div.className='toast'+(bad?' bad':'');div.textContent=message;document.body.appendChild(div);setTimeout(()=>div.remove(),4500)}
const request=async(fn)=>{try{return await fn()}catch(e){toast(e.message,true);return null}};
const formObj=form=>Object.fromEntries(new FormData(form).entries());
function modal(title,content){document.querySelector('.modal-backdrop')?.remove();const n=document.createElement('div');n.className='modal-backdrop';n.innerHTML=`<div class="modal" role="dialog" aria-modal="true"><div class="modal-top"><h2>${E(title)}</h2><button class="btn btn-small" data-action="close-modal">✕ Close</button></div><div class="modal-body">${content}</div></div>`;document.body.appendChild(n)}
function go(path){history.pushState({},'',path);modalClose();render();}
function modalClose(){$('.modal-backdrop')?.remove()}
const shopMenu=[['/shop/dashboard','▦','Overview'],['/shop/pos','▣','Counter POS'],['/shop/sales','▤',"Today's Sales"],['/shop/orders','▱','WooCommerce Orders'],['/shop/customers','♙','Customers'],['/shop/stock','▧','Shop Stock'],['/shop/requests','⇄','Stock Requests'],['/shop/drawer','▣','Cash Drawer']];
const warehouseMenu=[['/warehouse/dashboard','▦','Overview'],['/warehouse/inventory','▧','Warehouse Stock'],['/warehouse/requests','⇄','Stock Requests'],['/warehouse/movements','☷','Stock History'],['/warehouse/purchasing','⬡','Purchase Orders'],['/warehouse/suppliers','♙','Suppliers']];
const adminMenu=[['/admin/dashboard','▦','Overview'],['/admin/employees','♙','Employees'],['/admin/products','▧','Product Catalog'],['/admin/reports','▤','Business Reports'],['/admin/audit','☷','Audit Logs'],['/admin/integrations','↻','WooCommerce']];
function menu(){if(isAdmin())return [['ADMIN',adminMenu],['SHOP',shopMenu],['WAREHOUSE',warehouseMenu]];return me.role.startsWith('warehouse')?[['WAREHOUSE',warehouseMenu]]:[['SHOP',shopMenu]]}
function pageName(){const list=[...adminMenu,...shopMenu,...warehouseMenu];return list.find(x=>x[0]===location.pathname)?.[2]||'Dashboard'}
function shell(){const menuHTML=menu().map(([label,links])=>`<div class="hide-collapse side-group-title">${label}</div>${links.map(([path,ico,txt])=>`<button title="${E(txt)}" class="side-link ${path===location.pathname?'active':''}" data-go="${path}"><span class="side-ico">${ico}</span><span class="hide-collapse">${E(txt)}</span></button>`).join('')}`).join('');
 $('#app').innerHTML=`<div class="app-shell"><aside id="sidebar" class="sidebar ${collapsed?'collapsed':''}"><div class="brand"><span class="paw">🐾</span><span class="hide-collapse">petsdunya<strong>.</strong><span class="brand-sub">OPERATIONS</span></span></div><div class="location-tile hide-collapse"><b>Pet Store ERP</b><div class="small" style="margin-top:5px">${roleName(me.role)}</div></div><nav>${menuHTML}</nav><div class="side-foot"><div class="hide-collapse"><b>${E(me.name)}</b><div class="small tiny">${E(me.email)}</div></div><button class="side-link" data-action="change-password-modal"><span class="side-ico">⚙</span><span class="hide-collapse">Change password</span></button><button class="side-link" data-action="logout"><span class="side-ico">⇥</span><span class="hide-collapse">Sign out</span></button></div></aside><main class="main"><header class="topbar"><button data-action="sidebar" title="Menu">☰</button>${(location.pathname.startsWith('/shop')?`<button class="${location.pathname==='/shop/pos'?'primary':''}" data-go="/shop/pos">New sale</button><button class="${location.pathname==='/shop/sales'?'primary':''}" data-go="/shop/sales">Today's sales</button><button class="${location.pathname==='/shop/customers'?'primary':''}" data-go="/shop/customers">Customers</button>`:`<span class="semibold" style="margin-left:8px">${E(pageName())}</span>`)}<span class="spacer"></span><span class="tag top-hide-mobile">● ${E(roleName(me.role))}</span><button data-action="reload" title="Refresh">↻</button></header><div class="page" id="page-content"><div class="card card-pad"><span class="spinner"></span> Loading…</div></div><div class="footer-note">Pet Store ERP · Server-backed records · PKR · Asia/Karachi</div></main></div>`;
}
function loginPortal(){return location.pathname.startsWith('/admin')?'admin':location.pathname.startsWith('/warehouse')?'warehouse':'shop'}
function resetPage(){const token=new URLSearchParams(location.search).get('token')||'';$('#app').innerHTML=`<div class="auth-right" style="min-height:100vh"><div class="auth-card"><h2>Reset your password</h2><p>Enter a new password with at least 12 characters.</p><form data-form="reset-password"><input type="hidden" name="token" value="${E(token)}">${field('new_password','New password','password','minlength="12"')}<button class="btn btn-primary">Update password</button></form><p><a href="/shop/login">Back to sign in</a></p></div></div>`}
function loginPage(){const portal=loginPortal(),title=portal==='admin'?'Administrator':portal==='warehouse'?'Warehouse':'Shop POS';$('#app').innerHTML=`<section class="auth-shell"><div class="auth-brand"><div class="semibold" style="font-size:23px">🐾 petsdunya<span style="color:#c34e30">.</span></div><h1>${E(title)}<br>Operations.</h1><p>A connected retail ERP for your shop, warehouse, staff, inventory and WooCommerce orders.</p><div class="auth-orb"></div></div><div class="auth-right"><div class="auth-card"><div class="small count">SECURE ${E(portal.toUpperCase())} ACCESS</div><h2>Welcome back</h2><p>Sign in to access your ${E(title.toLowerCase())} dashboard.</p><form data-form="login"><div class="field"><label>Email address</label><input name="email" type="email" placeholder="you@company.com" autocomplete="username" required></div><div class="field"><label>Password</label><input name="password" type="password" minlength="12" placeholder="Enter password" autocomplete="current-password" required></div><button type="submit" class="btn btn-primary">Sign in securely →</button><button type="button" class="btn btn-outline" style="margin-top:12px;width:100%" data-action="forgot-modal">Forgot password?</button></form><div class="auth-switch"><a href="/admin/login">Admin</a><a href="/shop/login">Shop</a><a href="/warehouse/login">Warehouse</a></div><div class="tip small">Accounts are created by the administrator. Public registration is disabled.</div></div></div></section>`;}
async function render(){if(location.pathname==='/reset-password'){resetPage();return;}if(!me){loginPage();return;}const allowed=isAdmin()||(location.pathname.startsWith('/warehouse')&&me.role.startsWith('warehouse'))||(location.pathname.startsWith('/shop')&&['shop_manager','cashier'].includes(me.role));
 if(!allowed){go(me.role.startsWith('warehouse')?'/warehouse/dashboard':'/shop/dashboard');return;}
 shell();const path=location.pathname;
 try{if(path==='/admin/dashboard')await adminDashboard();else if(path==='/admin/employees')await employeesPage();else if(path==='/admin/products')await productsPage();else if(path==='/admin/reports')await adminReports();else if(path==='/admin/audit')await auditPage();else if(path==='/admin/integrations')await integrationsPage();
 else if(path==='/shop/dashboard')await shopDashboard();else if(path==='/shop/pos')await posPage();else if(path==='/shop/sales')await salesPage();else if(path==='/shop/customers')await customersPage();else if(path==='/shop/stock')await shopStock();else if(path==='/shop/requests')await shopRequests();else if(path==='/shop/orders')await ordersPage();else if(path==='/shop/drawer')await drawerPage();
 else if(path==='/warehouse/dashboard')await warehouseDashboard();else if(path==='/warehouse/inventory')await warehouseInventory();else if(path==='/warehouse/requests')await warehouseRequests();else if(path==='/warehouse/movements')await movementsPage();else if(path==='/warehouse/purchasing')await purchasesPage();else if(path==='/warehouse/suppliers')await suppliersPage();else go(isAdmin()?'/admin/dashboard':me.role.startsWith('warehouse')?'/warehouse/dashboard':'/shop/dashboard');
 }catch(e){$('#page-content').innerHTML=errorView(e)}
}
function header(title,subtitle='',actions=''){return `<div class="page-title"><div><h1>${E(title)}</h1>${subtitle?`<p>${E(subtitle)}</p>`:''}</div>${actions?`<div class="btn-row">${actions}</div>`:''}</div>`}
function stats(items){return `<div class="grid-stats">${items.map(([label,value,hint])=>`<div class="stat"><div class="muted semibold">${E(label)}</div><div class="value">${E(value)}</div><div class="small muted">${E(hint||'')}</div></div>`).join('')}</div>`}
function tabTable(head,rows){return `<div class="card table-scroll"><table><thead><tr>${head.map(x=>`<th>${E(x)}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${head.length}" class="empty">No records found.</td></tr>`}</tbody></table></div>`}
async function adminDashboard(){const d=await get('/admin/overview'),qty=k=>d.stock.find(x=>x.kind===k)?.quantity||0;
 $('#page-content').innerHTML=header('Operations overview','Shop, warehouse and WooCommerce activity')+stats([['Sales today',fmt(d.sales.amount)],['Sales recorded',d.sales.count],['Warehouse units',qty('warehouse')],['Shop units',qty('shop')],['Pending requests',d.requests.pending],['Woo orders cached',d.woocommerce.count],['Active employees',d.staff.count]])+`<div class="section twin"><div class="card card-pad"><h3>Shop counter</h3><p class="muted">Run new sales, look up customers and print thermal receipts.</p><button class="btn btn-primary" data-go="/shop/pos">Open Counter POS →</button></div><div class="card card-pad"><h3>Warehouse management</h3><p class="muted">Receive inventory, dispatch to shop, and view historical movements.</p><button class="btn btn-dark" data-go="/warehouse/dashboard">Open Warehouse →</button></div></div><div class="tip">Live WooCommerce orders appear after connecting your store and clicking Sync Orders. Stock quantities are tracked separately for each location.</div>`;}
async function shopDashboard(){const d=await get('/shop/overview');$('#page-content').innerHTML=header('Shop Dashboard','Counter sales and stock at your assigned shop')+stats([['Sales today',d.sales.count],['Revenue today',fmt(d.sales.revenue)],['Stocked products',d.stock.products],['Low stock lines',d.stock.low_stock],['Open stock requests',d.requests.pending]])+`<div class="section twin"><div class="card card-pad"><h3>Make a new sale</h3><p class="muted">Search by product name or SKU, select customer and charge.</p><button class="btn btn-primary" data-go="/shop/pos">Start new sale</button></div><div class="card card-pad"><h3>Incoming stock</h3><p class="muted">Check requests and confirm what your shop has received.</p><button class="btn" data-go="/shop/requests">See stock requests</button></div></div>`;}
async function warehouseDashboard(){const d=await get('/warehouse/overview');$('#page-content').innerHTML=header('Warehouse Dashboard','Physical inventory, requests and purchasing')+stats([['Products',d.stock.products],['Units in warehouse',d.stock.units],['Low stock lines',d.stock.low_stock],['Pending requests',d.requests.pending],['Open purchase orders',d.purchasing.count]])+`<div class="section twin"><div class="card card-pad"><h3>Inventory control</h3><p class="muted">Record goods received, damaged products and stock history.</p><button class="btn btn-primary" data-go="/warehouse/inventory">Manage inventory</button></div><div class="card card-pad"><h3>Shop transfers</h3><p class="muted">Approve requests and dispatch warehouse goods to the shop.</p><button class="btn btn-dark" data-go="/warehouse/requests">Open transfers</button></div></div>`;}
let productCache=new Map(),customerCache=new Map();
function cartSubtotal(){return cart.reduce((s,x)=>s+x.price_paisa*x.qty,0)}
function cartTotal(){return Math.max(0,cartSubtotal()-discount+delivery)}
function productCard(p){return `<button class="product-option" data-action="add-product" data-id="${p.id}" style="width:100%;text-align:left"><span class="product-thumb" style="display:grid;place-items:center">${p.image_url?`<img src="${E(p.image_url)}" alt="" width="38" height="38" style="object-fit:contain">`:'📦'}</span><span class="info"><b>${E(p.name)}</b><div class="muted small">SKU ${E(p.sku||'—')} · ${p.quantity} in shop</div></span><strong>${fmt(p.price_paisa)}</strong></button>`}
async function posPage(){
 const [products,customers,drawer]=await Promise.all([get('/shared/products?location_id='+shopId()+'&limit=8'),get('/shared/customers?q='),get('/shop/drawer?location_id='+shopId())]);productCache=new Map(products.map(p=>[String(p.id),p]));customerCache=new Map(customers.map(c=>[String(c.id),c]));
 $('#page-content').innerHTML=`<div class="pos-layout"><section class="pos-left"><div class="card card-pad"><div class="pos-customer-label"><span class="step">1</span><b>Customer — mobile, name ya pet ka naam poochein</b></div><input id="customerSearch" autocomplete="off" placeholder="03xx xxxxxxx · owner name · pet name · C-00012"><div class="recents"><span class="small muted" style="padding:10px">Recent</span><button class="recent" data-action="select-customer" data-id="0"><b>Walk-in</b><span>no details</span></button>${customers.slice(0,6).map(c=>`<button class="recent" data-action="select-customer" data-id="${c.id}"><b>${E(c.name)}</b><span>🐾 ${E(c.pet_name||'customer')}</span></button>`).join('')}</div><div id="customerMatches"></div><button class="btn btn-small" style="margin-top:9px" data-action="create-customer">+ New customer</button></div>
 <div class="card card-pad"><div class="checkout-info"><span>🚚</span><div class="segmented" id="saleTypeBtns"><button class="${saleKind==='on_site'?'active':''}" data-action="sale-kind" data-value="on_site">On-site sale</button><button class="${saleKind==='delivery'?'active':''}" data-action="sale-kind" data-value="delivery">Delivery</button></div></div><div id="deliveryNote" class="small muted">${saleKind==='delivery'?'Delivery charges can be entered in the payment panel.':'Counter pickup / walk-in'}</div></div>
 <div class="card card-pad"><div class="pos-customer-label"><span class="step">2</span><b>Add product — type name, brand, size or scan SKU</b></div><input id="productSearch" autocomplete="off" placeholder="Add product — type name, brand, size or scan SKU"><div class="tip small">Type to search WooCommerce products or locally created products.</div><div id="productMatches" class="product-results">${products.map(productCard).join('')}</div></div>
 <div class="card pos-cart"><div class="card-head" style="display:flex;justify-content:space-between"><span>Order</span><span class="small muted" id="cartCount">0 items</span></div><div id="cartItems"><div class="empty">Upar search se product add karein.</div></div></div></section>
 <aside class="payment-panel"><div class="small semibold">BILL TO</div><h3 id="billName" style="margin:7px 0 5px">${E(selectedCustomer?.name||'Walk-in customer')}</h3><span class="small" style="background:#f8eedc;color:#233;display:inline-block;padding:6px;border-radius:4px">Shop prices</span><div class="divide"></div><div class="btn-row" style="justify-content:space-between"><span class="semibold">Total to collect</span><span class="payment-total" id="paymentTotal">Rs 0</span></div><div class="pay-fields"><label>Discount (Rs)</label><input id="discountInput" type="number" min="0" step="0.01" value="${discount/100}"><div id="deliveryField" class="${saleKind==='delivery'?'':'hide'}" style="margin-top:11px"><label>Delivery charge (Rs)</label><input id="deliveryInput" type="number" min="0" step="0.01" value="${delivery/100}"></div><div class="segmented" style="margin-top:18px" id="paymentMethods"><button class="${payMethod==='cash'?'active':''}" data-action="payment-method" data-value="cash">💵 Cash</button><button class="${payMethod!=='cash'?'active':''}" data-action="payment-method" data-value="wallet">📱 Online</button></div><div id="paymentFields"></div></div><button class="btn-charge" id="chargeBtn" data-action="checkout" disabled>Charge Rs 0&nbsp; F9</button><div class="divide"></div><div class="small" style="color:#b5c9cf">Shortcuts: F2 customer · F3 product · F4 cash · F9 charge</div></aside></div>`;
 refreshCart();renderPaymentFields();const drawerBadge=$('.topbar .tag');if(drawerBadge)drawerBadge.textContent=(drawer.active?'● Drawer open':'○ Drawer not activated')+' · '+roleName(me.role);
}
function refreshCart(){let target=$('#cartItems');if(!target)return;const total=cartTotal(),sub=cartSubtotal();
 target.innerHTML=cart.length?cart.map((x,i)=>`<div class="cart-line"><span style="font-size:26px">📦</span><div style="flex:1"><strong>${E(x.name)}</strong><div class="small muted">${E(x.sku||'No SKU')} · ${fmt(x.price_paisa)} each</div><div class="cart-qty"><button data-action="cart-minus" data-index="${i}">−</button><span style="padding:5px 12px;background:white;border:1px solid #dfd2c0;border-radius:5px">${x.qty}</span><button data-action="cart-plus" data-index="${i}">+</button><button class="btn btn-small btn-danger" data-action="cart-remove" data-index="${i}">✕</button></div></div><div class="total">${fmt(x.price_paisa*x.qty)}</div></div>`).join('')+`<div class="card-pad small"><div class="btn-row" style="justify-content:space-between"><b>Subtotal: ${fmt(sub)}</b><b>Discount: ${fmt(discount)}</b><b>Total: ${fmt(total)}</b></div></div>`:`<div class="empty">Upar search se product add karein.</div>`;
 if($('#paymentTotal'))$('#paymentTotal').textContent=fmt(total);
 if($('#cartCount'))$('#cartCount').textContent=`${cart.reduce((a,b)=>a+b.qty,0)} items`;
 if($('#chargeBtn')){$('#chargeBtn').textContent=`Charge ${fmt(total)}  F9`;$('#chargeBtn').disabled=cart.length===0||discount>sub;}
}
function renderPaymentFields(){let el=$('#paymentFields');if(!el)return;el.innerHTML=payMethod==='cash'?`<div class="field"><label>Cash received (Rs)</label><input id="cashReceived" type="number" min="0" step="0.01" value="${cartTotal()/100}" placeholder="0"></div><div id="cashChange" class="small muted">Change due: Rs 0</div>`:`<div class="field"><label>Payment type</label><div class="segmented"><button data-action="payment-method" data-value="wallet" class="${payMethod==='wallet'?'active':''}">Wallet</button><button data-action="payment-method" data-value="bank" class="${payMethod==='bank'?'active':''}">Bank</button></div></div><div class="field"><label>Reference / Transaction ID</label><input id="paymentReference" placeholder="Bank or wallet transaction reference" required></div><p class="small" style="color:#bfd0d3">Online payments are saved as unverified until the manager confirms them externally.</p>`;}
async function searchProducts(q){if(!$('#productMatches'))return;const list=await get('/shared/products?location_id='+shopId()+'&q='+encodeURIComponent(q)+'&limit=35');for(const p of list)productCache.set(String(p.id),p);if($('#productMatches'))$('#productMatches').innerHTML=list.length?list.map(productCard).join(''):'<p class="muted">No matching products.</p>'}
async function searchCustomers(q){const list=await get('/shared/customers?q='+encodeURIComponent(q));for(const c of list)customerCache.set(String(c.id),c);if($('#customerMatches'))$('#customerMatches').innerHTML=q?`<div class="card" style="margin-top:7px">${list.map(c=>`<button class="product-option" data-action="select-customer" data-id="${c.id}" style="width:98%;margin:6px"><b>${E(c.name)}</b><span class="small muted">${E(c.phone)} · 🐾 ${E(c.pet_name)}</span></button>`).join('')||'<p class="muted">No matching customers.</p>'}</div>`:'';}
async function charge(){if(!cart.length)return toast('Cart is empty',true);const paid=payMethod==='cash'?paisaFromInput($('#cashReceived')?.value||0):cartTotal(),reference=payMethod==='cash'?'':($('#paymentReference')?.value||'').trim();if(payMethod!=='cash'&&!reference)return toast('Enter transaction reference',true);if(paid<cartTotal())return toast('Cash received must cover total amount',true);if(discount>cartSubtotal())return toast('Discount exceeds subtotal',true);
 const btn=$('#chargeBtn');btn.disabled=true;btn.textContent='Saving sale…';try{checkoutKey??=uuid();const result=await post('/shop/sales',{location_id:shopId(),customer_id:selectedCustomer?.id||null,items:cart.map(p=>({product_id:p.id,quantity:p.qty})),discount_paisa:discount,delivery_paisa:delivery,payment_method:payMethod,payment_reference:reference,received_paisa:paid,sale_type:saleKind,idempotency_key:checkoutKey});const sale=await get('/shop/sales/'+result.id);toast('Sale #'+result.id+' saved successfully');cart=[];checkoutKey=null;selectedCustomer=null;discount=0;delivery=0;saleKind='on_site';payMethod='cash';await posPage();openPosReceipt(sale);}catch(e){toast(e.message,true);btn.disabled=false;btn.textContent='Charge '+fmt(cartTotal())}}
async function salesPage(){const [rows,wc]=await Promise.all([get('/shop/sales?location_id='+shopId()),get('/woo/status')]);$('#page-content').innerHTML=header("Today's sales · latest first",'Saved counter sales at this shop')+stats([['Recent sales',rows.length],['Sales value',fmt(rows.reduce((s,x)=>s+Number(x.total_paisa),0))]])+tabTable(['Receipt','Time · PKT','Customer','Type','Amount','Payment','Status','Receipt'],rows.map(s=>`<tr><td><b>POS-${s.id}</b></td><td>${dateTime(s.created_at)}</td><td>${E(s.customer_name)}</td><td>${E(s.sale_type)}</td><td>${fmt(s.total_paisa)}</td><td>${E(s.payment_method)}</td><td>${statusBadge(s.payment_verified?'verified':'unverified')}</td><td><button class="btn btn-small" data-action="pos-receipt" data-id="${s.id}">🖨 Print</button> ${wc.pos_push_enabled&&canManageShop()&&!s.wc_order_id&&s.sync_state==='local'?`<button class="btn btn-small" data-action="push-woo" data-id="${s.id}">Push to Woo</button>`:''}</td></tr>`).join(''));}
async function customersPage(){const list=await get('/shared/customers?q=');customerCache=new Map(list.map(x=>[String(x.id),x]));$('#page-content').innerHTML=header('Customers',`${list.length} recent records`,`<button class="btn btn-primary" data-action="create-customer">+ New customer</button>`)+`<div class="card card-pad"><input id="customerTableSearch" placeholder="Search by name, phone or pet"></div><div id="customerRows">${customerTable(list)}</div>`;}
function customerTable(list){return tabTable(['ID','Customer','Mobile','Pet','Area / Address','New Sale'],list.map(c=>`<tr><td>C-${String(c.id).padStart(5,'0')}</td><td><b>${E(c.name)}</b></td><td>${E(c.phone)}</td><td>${E(c.pet_name)}</td><td class="wrap">${E(c.address)}</td><td><button class="btn btn-small" data-action="new-sale-customer" data-id="${c.id}">New sale</button></td></tr>`).join(''))}
async function shopStock(){const list=await get('/shared/products?location_id='+shopId()+'&limit=100');$('#page-content').innerHTML=header('Shop Stock','Current physical stock at your shop',canManageShop()?`<button class="btn btn-primary" data-go="/shop/requests">Request stock from warehouse</button>`:'')+tabTable(['SKU','Product','Shop Qty','Price','Status'],list.map(p=>`<tr><td>${E(p.sku||'—')}</td><td><b>${E(p.name)}</b></td><td>${p.quantity}</td><td>${fmt(p.price_paisa)}</td><td>${statusBadge(p.quantity===0?'out_of_stock':p.quantity<=5?'low_stock':'in_stock')}</td></tr>`).join(''));}
async function shopRequests(){const list=await get('/shop/stock-requests?location_id='+shopId());window._requestCache=new Map(list.map(x=>[String(x.id),x]));$('#page-content').innerHTML=header('Shop Stock Requests','Shop → Warehouse transfer workflow',canManageShop()?`<button class="btn btn-primary" data-action="request-stock">+ Request stock</button>`:'')+`<div class="tip">Warehouse must approve and dispatch before you can receive products. Shop stock updates only after receipt confirmation.</div>`+tabTable(['Request','Created','Product','Qty','Dispatched','Received','Warehouse','Status','Action'],list.map(x=>`<tr><td>#TR-${x.id}</td><td>${dateTime(x.created_at)}</td><td>${E(x.product_name)}</td><td>${x.quantity}</td><td>${x.dispatched_quantity}</td><td>${x.received_quantity}</td><td>${E(x.warehouse_name)}</td><td>${statusBadge(x.status)}</td><td>${['in_transit','partially_received'].includes(x.status)&&canManageShop()?`<button class="btn btn-small" data-action="receive-transfer" data-id="${x.id}" data-remaining="${x.dispatched_quantity-x.received_quantity}">Confirm receipt</button>`:'—'} <button class="btn btn-small" data-action="print-transfer" data-id="${x.id}">Print</button></td></tr>`).join(''));}
async function warehouseInventory(){const list=await get('/warehouse/inventory?location_id='+whId());for(const p of list)productCache.set(String(p.id),p);$('#page-content').innerHTML=header('Warehouse Inventory','Live stock balances with auditable inward/outward history',canOperateWh()?`<button class="btn btn-primary" data-action="stock-in-modal">+ Stock inward</button>${canManageWh()?`<button class="btn" data-action="stock-out-modal">− Stock outward</button>`:''}`:'')+stats([['Tracked products',list.length],['Total units',list.reduce((s,x)=>s+Number(x.quantity),0)],['Out of stock',list.filter(x=>x.quantity===0).length]])+tabTable(['SKU','Product','Category','Quantity','Selling Price','Action'],list.map(p=>`<tr><td>${E(p.sku||'—')}</td><td><b>${E(p.name)}</b></td><td>${E(p.category)}</td><td>${p.quantity}</td><td>${fmt(p.price_paisa)}</td><td>${canOperateWh()?`<button class="btn btn-small" data-action="stock-in-modal" data-id="${p.id}">Receive</button> ${canManageWh()?`<button class="btn btn-small btn-danger" data-action="stock-out-modal" data-id="${p.id}">Remove</button>`:''}`:'View only'}</td></tr>`).join(''));}
async function warehouseRequests(){const rows=await get('/warehouse/requests?location_id='+whId());window._requestCache=new Map(rows.map(x=>[String(x.id),x]));$('#page-content').innerHTML=header('Warehouse Stock Requests','Approve requests, dispatch goods, and track incoming receipts')+tabTable(['Request','Product','Shop','Requested','Warehouse Qty','Approved','Dispatched','Status','Actions'],rows.map(r=>`<tr><td><b>TR-${r.id}</b><div class="small muted">${dateTime(r.created_at)}</div></td><td>${E(r.product_name)}</td><td>${E(r.shop_name)}</td><td>${r.quantity}</td><td>${r.warehouse_stock}</td><td>${r.approved_quantity??'—'}</td><td>${r.dispatched_quantity}</td><td>${statusBadge(r.status)}</td><td>${canManageWh()&&r.status==='pending'?`<button class="btn btn-small btn-primary" data-action="approve-transfer" data-id="${r.id}" data-qty="${r.quantity}">Approve</button> <button class="btn btn-small btn-danger" data-action="reject-transfer" data-id="${r.id}">Reject</button>`:canOperateWh()&&r.status==='approved'?`<button class="btn btn-small" data-action="dispatch-transfer" data-id="${r.id}" data-qty="${r.approved_quantity}">Dispatch</button>`:'—'} <button class="btn btn-small" data-action="print-transfer" data-id="${r.id}">Print</button></td></tr>`).join(''));}
async function movementsPage(){const rows=await get('/warehouse/movements?location_id='+whId());window._movementCache=new Map(rows.map(x=>[String(x.id),x]));$('#page-content').innerHTML=header('Warehouse Stock History','Immutable physical inventory movement ledger')+tabTable(['Movement','Time','Product','Change','Type','Reference','Employee','Notes'],rows.map(m=>`<tr><td>#${m.id}</td><td>${dateTime(m.created_at)}</td><td>${E(m.product_name)}</td><td class="${m.delta>0?'success':'error'}"><b>${m.delta>0?'+':''}${m.delta}</b></td><td>${E(m.type)}</td><td>${E(m.reference)}</td><td>${E(m.actor||'System')}</td><td class="wrap">${E(m.note)} <button class="btn btn-small" data-action="print-movement" data-id="${m.id}">Print</button></td></tr>`).join(''));}
async function suppliersPage(){const rows=await get('/warehouse/suppliers');$('#page-content').innerHTML=header('Suppliers','Manage warehouse purchasing suppliers',canManageWh()?`<button class="btn btn-primary" data-action="supplier-modal">+ Add supplier</button>`:'')+tabTable(['ID','Supplier','Phone','Email','Address'],rows.map(s=>`<tr><td>#${s.id}</td><td><b>${E(s.name)}</b></td><td>${E(s.phone)}</td><td>${E(s.email)}</td><td>${E(s.address)}</td></tr>`).join(''));}
async function purchasesPage(){const rows=await get('/warehouse/purchases?location_id='+whId());$('#page-content').innerHTML=header('Purchase Orders','Receive products into the warehouse',canManageWh()?`<button class="btn btn-primary" data-action="purchase-modal">+ New purchase order</button>`:'')+tabTable(['PO','Created','Supplier','Value','Status','Action'],rows.map(p=>`<tr><td><b>PO-${p.id}</b></td><td>${dateTime(p.created_at)}</td><td>${E(p.supplier)}</td><td>${fmt(p.total_paisa)}</td><td>${statusBadge(p.status)}</td><td>${canManageWh()&&p.status==='ordered'?`<button class="btn btn-small btn-primary" data-action="receive-purchase" data-id="${p.id}">Receive all</button>`:'—'} <button class="btn btn-small" data-action="print-purchase" data-id="${p.id}">Print</button></td></tr>`).join(''));}

async function drawerPage(){const d=await get('/shop/drawer?location_id='+shopId());$('#page-content').innerHTML=header('Cash Drawer','Physical cash drawer session tracking',canManageShop()?(d.active?`<button class="btn btn-primary" data-action="drawer-movement-modal">Cash in / out</button><button class="btn btn-danger" data-action="drawer-close-modal">Close drawer</button>`:`<button class="btn btn-primary" data-action="drawer-open-modal">Open drawer</button>`):'')+(d.active?stats([['Status','Open'],['Opening cash',fmt(d.session.opening_paisa)],['Expected cash',fmt(d.expected_paisa)],['Movements',d.movements.length]])+tabTable(['Time','Type','Amount','Notes'],d.movements.map(x=>`<tr><td>${dateTime(x.created_at)}</td><td>${E(x.type)}</td><td class="${Number(x.amount_paisa)>=0?'success':'error'}">${fmt(x.amount_paisa)}</td><td>${E(x.note)}</td></tr>`).join('')):`<div class="card card-pad"><h3>Drawer not activated</h3><p class="muted">Open a drawer to record cash collected during counter sales and optional cash in/out movements.</p><div class="tip">Only cash payments made while a drawer session is open are included in that session. Wallet and bank transfers are not physical cash.</div></div>`);}

async function ordersPage(){const rows=await get('/woo/orders');$('#page-content').innerHTML=header('WooCommerce Orders','Orders pulled from your WordPress WooCommerce store',canManageShop()?`<button class="btn btn-primary" data-action="sync-orders">↻ Sync orders</button>`:'')+`<div class="card card-pad"><input id="wooSearch" placeholder="Search order number, customer, mobile"><div class="small muted" style="margin-top:8px">This is the cached order list. Refresh after updating WooCommerce.</div></div><div id="wooResults">${wooTable(rows)}</div>`;}
function wooTable(list){return tabTable(['Order','Date · PKT','Customer','Phone','Payment','Amount','Status','Actions'],list.map(o=>`<tr><td><b>#${E(o.number)}</b></td><td>${dateTime(o.created_at)}</td><td>${E(o.customer_name)}</td><td>${E(o.phone)}</td><td>${E(o.payment_method)}</td><td>${E(o.currency)} ${rupees(o.total_paisa)}</td><td>${statusBadge(o.status)}</td><td><div class="table-actions"><button class="btn btn-small" data-action="woo-detail" data-id="${o.id}">View</button><button class="btn btn-small" data-action="woo-receipt" data-id="${o.id}">🖨 Print</button></div></td></tr>`).join(''))}
async function integrationsPage(){const data=await get('/woo/status');$('#page-content').innerHTML=header('WooCommerce Connection','Credentials are configured securely on the server')+`<div class="twin"><div class="card card-pad"><h3>Connection status</h3><p>${data.configured?statusBadge('configured'):statusBadge('not_configured')}</p><div class="small muted">Website: ${E(data.website||'Not configured')}</div><div class="tip">Place WC_URL, WC_CONSUMER_KEY and WC_CONSUMER_SECRET in the server environment. Never type API secrets into the browser.</div><div class="btn-row"><button class="btn" data-action="test-woo">Test API</button><button class="btn btn-primary" data-action="sync-products">Sync products</button><button class="btn" data-action="sync-orders">Sync orders</button></div></div><div class="card card-pad"><h3>POS → WooCommerce</h3><p class="muted">Explicit push is currently ${data.pos_push_enabled?'enabled':'disabled'}.</p><div class="tip">For safety, start with order reading and printing. Enabling POS order posting requires WC_PUSH_POS=true and product mapping checks.</div><button class="btn" data-go="/shop/orders">View Woo orders</button></div></div>`;}
async function employeesPage(){const list=await get('/admin/users'),locations=await get('/shared/locations');window._locOptions=locations;window._userCache=new Map(list.map(x=>[String(x.id),x]));$('#page-content').innerHTML=header('Employees','Administrator controls all accounts and portal permissions',`<button class="btn btn-primary" data-action="employee-modal">+ Add employee</button>`)+tabTable(['ID','Employee','Email','Role','Location','Active','Actions'],list.map(u=>`<tr><td>#${u.id}</td><td><b>${E(u.name)}</b></td><td>${E(u.email)}</td><td>${E(roleName(u.role))}</td><td>${E(u.location_name||'All')}</td><td>${statusBadge(u.active?'active':'disabled')}</td><td>${u.id!==me.id?`<button class="btn btn-small ${u.active?'btn-danger':''}" data-action="toggle-user" data-id="${u.id}" data-active="${u.active}">${u.active?'Disable':'Enable'}</button> <button class="btn btn-small" data-action="edit-employee" data-id="${u.id}">Edit access</button> <button class="btn btn-small" data-action="admin-reset-user" data-id="${u.id}">Reset password</button>`:'You'}</td></tr>`).join(''));}
async function productsPage(){const list=await get('/shared/products?location_id=1&limit=100');$('#page-content').innerHTML=header('Product Catalog','WooCommerce products and local products',`<button class="btn btn-primary" data-action="admin-product-modal">+ Create product</button><button class="btn" data-action="sync-products">↻ Sync Woo products</button>`)+tabTable(['ID','SKU','Product','Price','Shop Qty','WooCommerce Link'],list.map(p=>`<tr><td>#${p.id}</td><td>${E(p.sku||'—')}</td><td>${E(p.name)}</td><td>${fmt(p.price_paisa)}</td><td>${p.quantity}</td><td>${p.wc_id?'#'+p.wc_id:'Local'}</td></tr>`).join(''));}
async function adminReports(){const d=await get('/admin/reports');$('#page-content').innerHTML=header('Business Reports','Sales, payments and available stock')+`<div class="section"><h3>Sales by date (PKT)</h3>${tabTable(['Date','Orders','Sales revenue'],d.sales.map(x=>`<tr><td>${E(x.day)}</td><td>${x.orders}</td><td>${fmt(x.revenue_paisa)}</td></tr>`).join(''))}<h3>Payments</h3>${tabTable(['Method','Orders','Value'],d.by_method.map(x=>`<tr><td>${E(x.payment_method)}</td><td>${x.orders}</td><td>${fmt(x.revenue_paisa)}</td></tr>`).join(''))}<h3>Inventory summary</h3>${tabTable(['Location','Product','Quantity','Price'],d.inventory.map(x=>`<tr><td>${E(x.location)}</td><td>${E(x.product)}</td><td>${x.quantity}</td><td>${fmt(x.price_paisa)}</td></tr>`).join(''))}</div>`;}
async function auditPage(){const list=await get('/shared/audit');$('#page-content').innerHTML=header('Audit Logs','Important account, stock and order events')+tabTable(['ID','Time','User','Action','Entity','Reference'],list.map(x=>`<tr><td>${x.id}</td><td>${dateTime(x.created_at)}</td><td>${E(x.actor||'System')}</td><td>${E(x.action)}</td><td>${E(x.entity)}</td><td>${E(x.entity_id)}</td></tr>`).join(''));}
const field=(name,label,type='text',extra='')=>`<div class="field"><label>${E(label)}</label><input name="${E(name)}" type="${type}" ${extra.replace('required=false','')} ${extra.includes('required=false')?'':'required'}></div>`;
const selectProduct=(arr,selected='')=>`<div class="field"><label>Product</label><select name="product_id" required>${arr.map(p=>`<option value="${p.id}" ${String(p.id)===String(selected)?'selected':''}>${E(p.name)} · ${E(p.sku||'—')} (stock: ${p.quantity})</option>`).join('')}</select></div>`;
function formModal(title,name,body,submit='Save'){modal(title,`<form data-form="${name}">${body}<div class="form-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">${E(submit)}</button></div></form>`)}
async function modalFor(action,idValue){
 if(action==='create-customer')return formModal('New Customer','customer-new',field('name','Full name')+field('phone','Mobile number','tel','required=false')+field('pet_name','Pet name','text','required=false')+field('address','Address','text','required=false'),'Create customer');
 if(action==='employee-modal'){const options=(window._locOptions||[]).map(l=>`<option value="${l.id}">${E(l.name)} (${E(l.kind)})</option>`).join('');return formModal('Create employee','employee-new',field('name','Full name')+field('email','Email','email')+field('password','Temporary password (12+ characters)','password','minlength="12"')+`<div class="field"><label>Role</label><select name="role"><option value="cashier">Shop Cashier</option><option value="shop_manager">Shop Manager</option><option value="warehouse_staff">Warehouse Staff</option><option value="warehouse_manager">Warehouse Manager</option><option value="admin">Administrator</option></select></div><div class="field"><label>Location</label><select name="location_id"><option value="">None (admin only)</option>${options}</select></div>`,'Create account');}
 if(action==='admin-product-modal')return formModal('Create local product','admin-product',field('name','Product name')+field('sku','Unique SKU')+field('category','Category','text','required=false')+field('price','Selling price (Rs)','number','step="0.01" min="0"'),'Create product');
 if(action==='stock-in-modal'||action==='stock-out-modal'){
  const products=await get('/warehouse/inventory?location_id='+whId()),inward=action==='stock-in-modal';return formModal(inward?'Stock inward':'Stock outward',inward?'stock-in':'stock-out',selectProduct(products,idValue)+field('quantity','Quantity','number','min="1" step="1"')+(inward?field('reference','Supplier/reference no.','text','required=false')+field('note','Notes','text','required=false'):field('reason','Reason (required)')),'Confirm '+(inward?'inward':'outward'));
 }
 if(action==='request-stock'){
  const [products,locations]=await Promise.all([get('/shared/products?location_id='+shopId()+'&limit=100'),get('/shared/locations')]);return formModal('Request warehouse stock','stock-request',selectProduct(products)+`<div class="field"><label>Warehouse</label><select name="warehouse_id">${locations.filter(l=>l.kind==='warehouse').map(l=>`<option value="${l.id}">${E(l.name)}</option>`).join('')}</select></div>`+field('quantity','Quantity to request','number','min="1" step="1"')+field('reason','Request reason','text','required=false'),'Send request');
 }
 if(action==='supplier-modal')return formModal('Add supplier','supplier-new',field('name','Supplier name')+field('phone','Phone','tel','required=false')+field('email','Email','email','required=false')+field('address','Address','text','required=false'),'Save supplier');
 if(action==='purchase-modal'){
  const [products,suppliers]=await Promise.all([get('/warehouse/inventory?location_id='+whId()),get('/warehouse/suppliers')]);if(!suppliers.length)return toast('Add a supplier before creating a purchase order.',true);
  return formModal('New purchase order','purchase-new',`<div class="field"><label>Supplier</label><select name="supplier_id">${suppliers.map(x=>`<option value="${x.id}">${E(x.name)}</option>`).join('')}</select></div>`+selectProduct(products)+field('quantity','Quantity','number','min="1" step="1"')+field('cost','Unit purchase cost (Rs)','number','min="0" step="0.01"'),'Create purchase order');
 }
 if(['approve-transfer','dispatch-transfer','receive-transfer'].includes(action)){const remaining=Number(idValue.qty),text=action==='approve-transfer'?'Approve request':action==='dispatch-transfer'?'Dispatch from warehouse':'Confirm receipt at shop';return formModal(text,'transfer-'+action,`<input name="request_id" type="hidden" value="${idValue.id}">`+`<div class="tip">${action==='receive-transfer'?'Only actually received units should be confirmed.':'You may enter less than the maximum quantity.'}</div>`+`<div class="field"><label>Quantity (maximum ${remaining})</label><input type="number" name="quantity" min="1" max="${remaining}" value="${remaining}" required></div>`,text);
 }
 if(action==='reject-transfer')return formModal('Reject request','transfer-reject',`<input name="request_id" type="hidden" value="${idValue}">`+field('reason','Rejection reason'),'Reject');
 if(action==='drawer-open-modal')return formModal('Open Cash Drawer','drawer-open',field('opening','Opening cash (Rs)','number','min="0" step="0.01"'),'Open drawer');
 if(action==='drawer-movement-modal')return formModal('Record cash movement','drawer-movement',`<div class="field"><label>Movement</label><select name="type"><option value="cash_in">Cash in</option><option value="cash_out">Cash out</option></select></div>`+field('amount','Amount (Rs)','number','min="0.01" step="0.01"')+field('note','Reason','text','required=false'),'Record movement');
 if(action==='drawer-close-modal')return formModal('Close Cash Drawer','drawer-close',field('actual','Actual counted cash (Rs)','number','min="0" step="0.01"'),'Close drawer');
 if(action==='forgot-modal')return formModal('Recover account','forgot-password',field('email','Your account email','email'),'Email recovery link');
 if(action==='edit-employee'){const u=window._userCache?.get(String(idValue));if(!u)return toast('Employee not found',true);const locations=window._locOptions||[];return formModal('Edit employee access','edit-employee',`<input type="hidden" name="user_id" value="${u.id}">`+`<div class="field"><label>Name</label><input name="name" value="${E(u.name)}" required></div><div class="field"><label>Email</label><input name="email" type="email" value="${E(u.email)}" required></div><div class="field"><label>Role</label><select name="role">${['cashier','shop_manager','warehouse_staff','warehouse_manager','admin'].map(r=>`<option value="${r}" ${u.role===r?'selected':''}>${E(roleName(r))}</option>`).join('')}</select></div><div class="field"><label>Location</label><select name="location_id"><option value="">None (admin)</option>${locations.map(l=>`<option value="${l.id}" ${String(u.location_id)===String(l.id)?'selected':''}>${E(l.name)}</option>`).join('')}</select></div>`, 'Save access');}
 if(action==='admin-reset-user')return formModal('Reset employee password','admin-reset-user',`<input type="hidden" name="user_id" value="${E(idValue)}">`+field('new_password','New temporary password','password','minlength="12"'),'Reset password');
 if(action==='change-password-modal')return formModal('Change password','password-change',field('current_password','Current password','password')+field('new_password','New password (at least 12 characters)','password','minlength="12"'),'Change password');
}
function receiptFromPos(s){return {heading:'COUNTER SALE',number:`POS-${s.id}`,date:s.created_at,customer:s.customer_name,payment:s.payment_method+' · '+(s.payment_verified?'verified':'unverified'),lines:s.items.map(i=>({name:i.product_name,quantity:i.quantity,total:i.total_paisa})),subtotal:s.subtotal_paisa,discount:s.discount_paisa,shipping:s.delivery_paisa,total:s.total_paisa,received:s.payment_method==='cash'?s.received_paisa:null,change:s.payment_method==='cash'?s.change_paisa:null,currency:'Rs'};}
function receiptFromWoo(o){const x=o.payload,b=x.billing||{};return {heading:'WOOCOMMERCE ORDER',number:'#'+(o.number||o.id),date:o.created_at||x.date_created,customer:o.customer_name,phone:b.phone,address:[b.address_1,b.city].filter(Boolean).join(', '),payment:o.payment_method+' · '+o.status,lines:(x.line_items||[]).map(i=>({name:i.name,quantity:i.quantity,total:paisaFromInput(i.total)})),subtotal:(x.line_items||[]).reduce((a,i)=>a+paisaFromInput(i.subtotal),0),discount:paisaFromInput(x.discount_total),shipping:paisaFromInput(x.shipping_total),tax:paisaFromInput(x.total_tax),total:o.total_paisa,received:null,change:null,currency:o.currency==='PKR'?'Rs':o.currency};}

// Receipt-only printing v4: independent window, never print the POS application.
function printReceiptOnly(data,paper='80') {
  const size=paper==='58'?'58mm':paper==='a4'?'210mm':'80mm';
  const thermal=paper!=='a4';
  // Open synchronously in the click event to avoid the browser popup blocker.
  const win=window.open('','_blank','width=620,height=740');
  if(!win){toast('Please allow pop-ups for localhost:3000 to print receipts.',true);return;}
  const css=`@page{size:${thermal?`${size} 200mm`:'A4 portrait'};margin:0}
*{box-sizing:border-box}html,body{background:white!important;color:black!important;margin:0!important;padding:0!important;min-height:0!important;overflow:visible!important}
body{width:${size};max-width:100%;font-family:'Courier New',monospace;font-size:${paper==='58'?'8pt':thermal?'9pt':'11pt'};line-height:1.35}
.receipt-preview{background:#fff!important;color:#000!important;box-shadow:none!important;border:none!important;border-radius:0!important;display:block!important;position:static!important;width:${size}!important;max-width:100%!important;min-height:0!important;margin:0!important;padding:${thermal?'3mm 3mm':'12mm'}!important;overflow:visible!important}
.receipt-preview.a4{font-family:Arial,sans-serif}
.receipt-preview h2{text-align:center;font-size:${thermal?'13pt':'18pt'};margin:4px 0 8px}
.receipt-preview .center{text-align:center}
.receipt-preview .line{border-bottom:1px dashed #222;margin:8px 0}
.receipt-preview .rrow{display:flex;justify-content:space-between;align-items:baseline;gap:6px;margin:4px 0}
.receipt-preview .rrow span:last-child{text-align:right;white-space:nowrap}
.receipt-preview p{margin:3px 0;overflow-wrap:anywhere}
@media screen{body{margin:20px auto!important;box-shadow:0 2px 16px #ddd}}
@media print{html,body{width:${size}!important;margin:0!important;padding:0!important;box-shadow:none!important}body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
`;
  const html='<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Receipt '+String(data.number||'').replace(/[<>"&]/g,'')+'</title><style>'+css+'</style></head><body>'+receiptHTML(data,paper)+'</body></html>';
  win.document.open();win.document.write(html);win.document.close();
  // The print window contains only the receipt. No website/sidebar/modal HTML.
  win.focus();
  win.setTimeout(()=>{try{win.focus();win.print();}catch(e){alert('Print failed: '+e.message)}},500);
}

function receiptHTML(s,paper='80'){if(s.documentType==='record'){const cls=paper==='58'?'small':paper==='a4'?'a4':'';return `<div class="receipt-preview ${cls}"><h2>PET STORE ERP</h2><p class="center">${E(s.heading)}</p><div class="line"></div><p><b>Reference:</b> ${E(s.number)}</p><p><b>Date:</b> ${E(dateTime(s.date))}</p>${s.fields.map(([k,v])=>`<div class="rrow"><span>${E(k)}</span><b>${E(v)}</b></div>`).join('')}<div class="line"></div><p class="center">Warehouse operations record</p><div class="line"></div><p>Prepared by: __________________</p><p>Received by: __________________</p></div>`;}const cls=paper==='58'?'small':paper==='a4'?'a4':'';return `<div class="receipt-preview ${cls}"><h2>🐾 PET STORE</h2><div class="center">Retail & Pet Supplies<br>${E(s.heading)}</div><div class="line"></div><p><b>Receipt:</b> ${E(s.number)}</p><p><b>Date:</b> ${E(dateTime(s.date))}</p><p><b>Customer:</b> ${E(s.customer||'Walk-in')}</p>${s.phone?`<p><b>Phone:</b> ${E(s.phone)}</p>`:''}${s.address?`<p><b>Address:</b> ${E(s.address)}</p>`:''}<div class="line"></div>${s.lines.map(l=>`<p>${E(l.name)}</p><div class="rrow"><span>${l.quantity} × items</span><span>${E(s.currency)} ${rupees(l.total)}</span></div>`).join('')}<div class="line"></div><div class="rrow"><span>Subtotal</span><span>${E(s.currency)} ${rupees(s.subtotal)}</span></div>${s.discount?`<div class="rrow"><span>Discount</span><span>− ${E(s.currency)} ${rupees(s.discount)}</span></div>`:''}${s.shipping?`<div class="rrow"><span>Delivery</span><span>${E(s.currency)} ${rupees(s.shipping)}</span></div>`:''}${s.tax?`<div class="rrow"><span>Tax</span><span>${E(s.currency)} ${rupees(s.tax)}</span></div>`:''}<div class="line"></div><div class="rrow"><b>GRAND TOTAL</b><b>${E(s.currency)} ${rupees(s.total)}</b></div><div class="line"></div><p>Payment: ${E(s.payment)}</p>${s.received!==null?`<div class="rrow"><span>Received</span><span>${E(s.currency)} ${rupees(s.received)}</span></div><div class="rrow"><span>Change</span><span>${E(s.currency)} ${rupees(s.change)}</span></div>`:''}<div class="line"></div><p class="center">Thank you for shopping!<br>Visit us again.</p></div>`}
let currentReceipt=null;
function receiptModal(data){currentReceipt=data;modal('Receipt preview',`<div class="field" style="max-width:180px"><label>Paper size</label><select id="receiptPaper"><option value="80">80mm Thermal</option><option value="58">58mm Thermal</option><option value="a4">A4</option></select></div><div id="receiptPreview">${receiptHTML(data)}</div><div class="form-actions"><button class="btn" data-action="close-modal">Close</button><button class="btn btn-primary" data-action="print-receipt">🖨 Print receipt (v4)</button></div>`)}
function recordDoc(heading,number,date,fields){receiptModal({documentType:'record',heading,number,date,fields})}
function openPosReceipt(s){receiptModal(receiptFromPos(s))}
function openWooReceipt(o){receiptModal(receiptFromWoo(o))}
async function wooDetails(n){const o=await get('/woo/orders/'+n);const p=o.payload;modal('WooCommerce Order #'+o.number,`<div class="btn-row"><span>${statusBadge(o.status)}</span><b>${E(o.currency)} ${rupees(o.total_paisa)}</b></div><p><b>Customer:</b> ${E(o.customer_name)} · ${E(o.phone)} · ${E(o.email)}</p><p><b>Billing:</b> ${E([p.billing?.address_1,p.billing?.city,p.billing?.country].filter(Boolean).join(', '))}</p><p><b>Shipping:</b> ${E([p.shipping?.address_1,p.shipping?.city,p.shipping?.country].filter(Boolean).join(', '))}</p><p><b>Payment:</b> ${E(o.payment_method)}</p>${tabTable(['Product','SKU','Quantity','Line Total'],(p.line_items||[]).map(i=>`<tr><td class="wrap">${E(i.name)}</td><td>${E(i.sku)}</td><td>${i.quantity}</td><td>${E(o.currency)} ${rupees(paisaFromInput(i.total))}</td></tr>`).join(''))}<div class="form-actions"><button class="btn" data-action="close-modal">Close</button><button class="btn btn-primary" data-action="woo-receipt" data-id="${o.id}">🖨 Print receipt (v4)</button></div>`)}
let checkoutKey=null;
document.addEventListener('click',async ev=>{
 const b=ev.target.closest('[data-go],[data-action]');if(!b)return;
 ev.preventDefault();const path=b.dataset.go;if(path){go(path);return}
 const a=b.dataset.action,idx=Number(b.dataset.index),pId=b.dataset.id;
 try{
 if(a==='close-modal'){modalClose();return}
 if(a==='sidebar'){if(innerWidth<900)$('#sidebar')?.classList.toggle('open');else{collapsed=!collapsed;$('#sidebar')?.classList.toggle('collapsed',collapsed)}return}
 if(a==='reload'){await render();return}
 if(a==='logout'){await post('/auth/logout',{});me=null;cart=[];go('/shop/login');return}
 if(a==='select-customer'){selectedCustomer=pId==='0'?null:customerCache.get(String(pId));if($('#billName'))$('#billName').textContent=selectedCustomer?.name||'Walk-in customer';if($('#customerMatches'))$('#customerMatches').innerHTML='';if($('#customerSearch'))$('#customerSearch').value=selectedCustomer?.name||'';return}
 if(a==='new-sale-customer'){selectedCustomer=customerCache.get(String(pId));cart=[];discount=0;delivery=0;checkoutKey=null;go('/shop/pos');return}
 if(a==='add-product'){const p=productCache.get(String(pId));if(!p)return toast('Product not loaded',true);if(p.quantity<=0)return toast('Out of stock at this shop',true);const found=cart.find(x=>x.id===p.id);if(found){if(found.qty>=p.quantity)return toast('Not enough shop stock',true);found.qty++}else cart.push({...p,qty:1});checkoutKey=null;refreshCart();return}
 if(a==='cart-plus'){const c=cart[idx];if(c.qty>=c.quantity)return toast('Not enough shop stock',true);c.qty++;checkoutKey=null;refreshCart();return}
 if(a==='cart-minus'){const c=cart[idx];c.qty--;if(c.qty===0)cart.splice(idx,1);checkoutKey=null;refreshCart();return}
 if(a==='cart-remove'){cart.splice(idx,1);checkoutKey=null;refreshCart();return}
 if(a==='payment-method'){payMethod=b.dataset.value;$('#paymentMethods')?.querySelectorAll('button').forEach(x=>x.classList.toggle('active',(x.dataset.value==='cash')===(payMethod==='cash')));renderPaymentFields();return}
 if(a==='sale-kind'){saleKind=b.dataset.value;$('#saleTypeBtns')?.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x.dataset.value===saleKind));$('#deliveryField')?.classList.toggle('hide',saleKind!=='delivery');$('#deliveryNote').textContent=saleKind==='delivery'?'Set delivery charges in the payment panel.':'Counter pickup / walk-in';if(saleKind!=='delivery'){delivery=0;checkoutKey=null;if($('#deliveryInput'))$('#deliveryInput').value='0';refreshCart()}return}
 if(a==='checkout'){await charge();return}
 if(['create-customer','employee-modal','admin-product-modal','stock-in-modal','stock-out-modal','request-stock','supplier-modal','purchase-modal','change-password-modal','forgot-modal','admin-reset-user','edit-employee','drawer-open-modal','drawer-movement-modal','drawer-close-modal'].includes(a)){await modalFor(a,pId);return}
 if(['approve-transfer','dispatch-transfer','receive-transfer'].includes(a)){await modalFor(a,{id:pId,qty:Number(b.dataset.qty||b.dataset.remaining)});return}
 if(a==='reject-transfer'){await modalFor(a,pId);return}
 if(a==='receive-purchase'){if(!confirm('Receive ALL products from this purchase order into warehouse stock?'))return;await post('/warehouse/purchases/'+pId+'/receive',{location_id:whId()});toast('Purchase received and warehouse stock updated');await render();return}
 if(a==='toggle-user'){const active=b.dataset.active==='true';if(!confirm(`${active?'Disable':'Enable'} this employee?`))return;await patch('/admin/users/'+pId,{active:!active});toast('Employee status updated');await render();return}
 if(a==='push-woo'){if(!confirm('Post this sale to WooCommerce? Confirm product prices and stock synchronization in staging first.'))return;const result=await post('/woo/push-sale/'+pId,{});toast('WooCommerce order #'+result.wc_order_id+' created');await render();return}
 if(a==='pos-receipt'){const s=await get('/shop/sales/'+pId+'?location_id='+shopId());openPosReceipt(s);return}
 if(a==='woo-detail'){await wooDetails(pId);return}
 if(a==='woo-receipt'){openWooReceipt(await get('/woo/orders/'+pId));return}
 if(a==='print-transfer'){const r=window._requestCache?.get(String(pId));if(!r)return toast('Request unavailable',true);recordDoc('STOCK TRANSFER',`TR-${r.id}`,r.created_at,[['Product',r.product_name],['From',r.warehouse_name||'Warehouse'],['To',r.shop_name||'Shop'],['Requested',r.quantity],['Approved',r.approved_quantity??'—'],['Dispatched',r.dispatched_quantity],['Received',r.received_quantity],['Status',r.status]]);return}
 if(a==='print-movement'){const m=window._movementCache?.get(String(pId));if(!m)return toast('Movement unavailable',true);recordDoc('STOCK MOVEMENT',`MOV-${m.id}`,m.created_at,[['Product',m.product_name],['Quantity change',m.delta],['Type',m.type],['Reference',m.reference],['Employee',m.actor||'System'],['Notes',m.note]]);return}
 if(a==='print-purchase'){const x=await get('/warehouse/purchases/'+pId+'?location_id='+whId());recordDoc('PURCHASE ORDER',`PO-${x.id}`,x.created_at,[['Supplier',x.supplier],['Status',x.status],['Total',fmt(x.total_paisa)],...x.items.map(i=>[i.product_name,`${i.quantity} × ${fmt(i.cost_paisa)}`])]);return}
 if(a==='print-receipt'){if(!currentReceipt)return;const paper=$('#receiptPaper')?.value||'80';printReceiptOnly(currentReceipt,paper);return}
 if(a==='sync-products'||a==='sync-orders'||a==='test-woo'){
  b.disabled=true;b.textContent='Working…';try{const url=a==='sync-products'?'/woo/sync-products':a==='sync-orders'?'/woo/sync-orders':'/woo/test';const x=await post(url,{});toast(x.count!==undefined?`Synchronized ${x.count} records`:'Connection successful');await render()}finally{b.disabled=false}return;
 }
 }catch(e){toast(e.message,true);if(b?.isConnected)b.disabled=false}
});
document.addEventListener('submit',async event=>{
 const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();const kind=form.dataset.form,d=formObj(form),btn=form.querySelector('[type=submit]');if(btn)btn.disabled=true;
 try{
  if(kind==='login'){const portal=loginPortal(),result=await post('/auth/login',{email:d.email,password:d.password,portal});me=result.user;toast('Welcome '+me.name);go('/'+portal+'/dashboard');return}
  if(kind==='customer-new'){const c=await post('/shared/customers',d);customerCache.set(String(c.id),c);selectedCustomer=c;toast('Customer created');modalClose();await render();return}
  if(kind==='employee-new'){await post('/admin/users',{...d,location_id:d.location_id||null});toast('Employee created');modalClose();await render();return}
  if(kind==='admin-product'){await post('/admin/products',d);toast('Product created');modalClose();await render();return}
  if(kind==='stock-in'){await post('/warehouse/stock-in',{...d,location_id:whId(),quantity:Number(d.quantity)});toast('Stock received');modalClose();await render();return}
  if(kind==='stock-out'){await post('/warehouse/stock-out',{...d,location_id:whId(),quantity:Number(d.quantity)});toast('Stock outward recorded');modalClose();await render();return}
  if(kind==='stock-request'){await post('/shop/stock-requests',{...d,location_id:shopId(),quantity:Number(d.quantity)});toast('Warehouse request created');modalClose();await render();return}
  if(kind==='supplier-new'){await post('/warehouse/suppliers',d);toast('Supplier created');modalClose();await render();return}
  if(kind==='purchase-new'){await post('/warehouse/purchases',{supplier_id:Number(d.supplier_id),location_id:whId(),items:[{product_id:Number(d.product_id),quantity:Number(d.quantity),cost_paisa:paisaFromInput(d.cost)}]});toast('Purchase order created');modalClose();await render();return}
  if(kind==='transfer-approve'){await post('/warehouse/requests/'+d.request_id+'/approve',{location_id:whId(),quantity:Number(d.quantity)});toast('Stock request approved');modalClose();await render();return}
  if(kind==='transfer-reject'){await post('/warehouse/requests/'+d.request_id+'/reject',{location_id:whId(),reason:d.reason});toast('Stock request rejected');modalClose();await render();return}
  if(kind==='transfer-dispatch'){await post('/warehouse/requests/'+d.request_id+'/dispatch',{location_id:whId(),quantity:Number(d.quantity)});toast('Stock dispatched and marked in transit');modalClose();await render();return}
  if(kind==='transfer-receive'){await post('/shop/stock-requests/'+d.request_id+'/receive',{location_id:shopId(),quantity:Number(d.quantity)});toast('Shop stock increased by received quantity');modalClose();await render();return}
  if(kind==='drawer-open'){await post('/shop/drawer/open',{location_id:shopId(),opening_paisa:paisaFromInput(d.opening)});toast('Drawer opened');modalClose();await render();return}
  if(kind==='drawer-movement'){await post('/shop/drawer/movement',{location_id:shopId(),type:d.type,amount_paisa:paisaFromInput(d.amount),note:d.note});toast('Cash movement recorded');modalClose();await render();return}
  if(kind==='drawer-close'){const x=await post('/shop/drawer/close',{location_id:shopId(),actual_paisa:paisaFromInput(d.actual)});toast('Drawer closed. Difference: '+fmt(x.difference_paisa));modalClose();await render();return}
  if(kind==='forgot-password'){const x=await post('/auth/forgot-password',d);toast(x.message);modalClose();return}
  if(kind==='reset-password'){await post('/auth/reset-password',d);toast('Password updated. You can sign in.');go('/shop/login');return}
  if(kind==='edit-employee'){await patch('/admin/users/'+d.user_id,{name:d.name,email:d.email,role:d.role,location_id:d.location_id||null});toast('Employee access updated');modalClose();await render();return}
  if(kind==='admin-reset-user'){await post('/admin/users/'+d.user_id+'/reset-password',{new_password:d.new_password});toast('Password reset and sessions revoked');modalClose();return}
  if(kind==='password-change'){await post('/auth/change-password',d);me=null;toast('Password changed. Sign in again.');go('/shop/login');return}
 }catch(e){toast(e.message,true)}finally{if(btn?.isConnected)btn.disabled=false}
});
document.addEventListener('input',event=>{
 const t=event.target;
 if(t.id==='productSearch'){clearTimeout(searchTimer);searchTimer=setTimeout(()=>request(()=>searchProducts(t.value)),250)}
 if(t.id==='customerSearch'){clearTimeout(searchTimer);searchTimer=setTimeout(()=>request(()=>searchCustomers(t.value)),250)}
 if(t.id==='wooSearch'){clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{const q=t.value.trim();await request(async()=>{const rows=await get('/woo/orders?q='+encodeURIComponent(q));if($('#wooResults'))$('#wooResults').innerHTML=wooTable(rows)})},250)}
 if(t.id==='customerTableSearch'){clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{await request(async()=>{const rows=await get('/shared/customers?q='+encodeURIComponent(t.value));for(const x of rows)customerCache.set(String(x.id),x);if($('#customerRows'))$('#customerRows').innerHTML=customerTable(rows)})},250)}
 if(t.id==='discountInput'){discount=paisaFromInput(t.value);checkoutKey=null;refreshCart()}
 if(t.id==='deliveryInput'){delivery=paisaFromInput(t.value);checkoutKey=null;refreshCart()}
 if(t.id==='cashReceived'&&$('#cashChange'))$('#cashChange').textContent='Change due: '+fmt(Math.max(0,paisaFromInput(t.value)-cartTotal()));
 if(t.id==='receiptPaper'&&currentReceipt)$('#receiptPreview').innerHTML=receiptHTML(currentReceipt,t.value);
});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'){modalClose();return}
 if(e.ctrlKey&&e.key.toLowerCase()==='k'){e.preventDefault();$('#productSearch')?.focus();return}
 if(location.pathname==='/shop/pos'){
  if(e.key==='F2'){e.preventDefault();$('#customerSearch')?.focus()}
  if(e.key==='F3'){e.preventDefault();$('#productSearch')?.focus()}
  if(e.key==='F4'){e.preventDefault();$('#cashReceived')?.focus()}
  if(e.key==='F9'){e.preventDefault();if(!$('#chargeBtn')?.disabled)charge()}
 }
});
window.addEventListener('popstate',()=>render());
(async()=>{try{const d=await get('/auth/me');me=d.user;}catch{me=null}
 const path=location.pathname;if(me&&/\/login$/.test(path)){const portal=isAdmin()?'admin':me.role.startsWith('warehouse')?'warehouse':'shop';history.replaceState({},'','/'+portal+'/dashboard')}
 if(!me&&!/\/login$/.test(path)&&path!=='/reset-password')history.replaceState({},'','/shop/login');await render();})();
